message.content:
{
  "events": [
    {
      "key": "ft_iron_lunch",
      "story": "가질이 식사할 철을 고르던 자리에 아직 의자에 끼워야 할 부품이 섞여 있다. 미라젠은 먹어도 되는 철을 먼저 나누자고 하고 가질은 어느 쪽이 식사인지 표시부터 하라고 한다. 너는 구분을 돕거나 바깥에서 부품을 가져오는 쪽을 맡을 수 있다.",
      "intro": "길드 내의 분주한 분위기 속에서 가질의 식사 준비가 시작된다.",
      "choices": [
        {
          "label": "분류 용품을 마련해 가질과 먹을 철을 나눈다",
          "result": "분류 용품을 지불하고 가질의 식사 재료를 명확히 구분하였다. 공격을 이어 가며 버틸 힘을 얻고 일격에 힘을 싣는 요령을 배웠으며, 200골드를 지불했다. 가질의 식사가 정리되는 것을 확인하며 다음 구역을 살핀다."
        },
        {
          "label": "나츠와 더 강한 적이 오가는 부품 길목을 맡는다",
          "result": "외부에서 부품을 가져오는 역할을 맡아 나츠와 함께 이동한다. 공격에 힘을 싣고 작은 상대를 처리하는 요령을 배웠고, 개인 적의 강함이 1 상승했으며 적의 수가 1명 늘어났다. 부품을 확보하며 주변을 경계한다."
        },
        {
          "label": "사용할 부품만 정리하고 작업 보수를 받는다",
          "result": "부품을 정리하는 작업에 집중하여 보수를 챙긴다. 140골드를 받았으며 추가적인 요령이나 변화는 없다. 정리가 끝난 후 미라젠에게 보고한다."
        }
      ]
    },
    {
      "key": "ft_two_umbrellas",
      "story": "쥬비아가 그레이가 돌아올 쪽에 우산을 챙겨 두자 다른 사람이 쓸 것은 남았냐는 말이 나온다. 쥬비아는 그레이 몫을 먼저 보려 하고 미라젠은 돌아오는 사람의 수부터 세자고 한다. 그레이는 자신에게 두 개가 필요하지는 않다며 다른 쪽을 가리킨다.",
      "intro": "쥬비아의 세심한 배려와 미라젠의 현실적인 조율이 겹치는 상황이다.",
      "choices": [
        {
          "label": "우산 표시 용품을 내고 쥬비아와 돌아올 몫을 나눈다",
          "result": "우산 표시 용품을 지불하고 쥬비아의 요청에 따라 물량을 배분한다. 몸 상태를 오래 유지하는 요령을 배웠으며 180골드를 지불했다. 배분이 완료된 후 우산 거치대를 확인한다."
        },
        {
          "label": "그레이와 더 많은 적이 오가는 바깥 길목을 맡는다",
          "result": "그레이와 동행하며 외부의 위험 요소에 대비한다. 힘을 모으며 넓은 범위를 살피는 공격 요령을 배웠고, 개인 적의 강함이 1 상승했으며 적의 수가 1명 늘어났다. 외곽을 순찰하며 길을 확보한다."
        },
        {
          "label": "맡을 길목을 줄이고 남은 우산을 정리한다",
          "result": "담당 구역을 좁히는 대신 남은 우산 수량을 정리한다. 120골드를 받았으며 물약 1개를 획득했다. 적의 수가 1명 줄어들었으며 정리가 끝난 후 휴식을 취한다."
        }
      ]
    },
    {
      "key": "ft_magazine_queue",
      "story": "길드를 찾아온 방문객이 미라젠의 잡지 사진을 내밀자 뒤의 의뢰인은 자기 부탁도 들을 차례라고 한다. 미라젠은 사진을 보고 온 사람과 일 때문에 온 사람이 뒤섞였다고 말한다. 루시는 의뢰서를 받아 놓고 먼저 어떤 말을 하러 왔는지 나누자고 한다.",
      "intro": "미라젠의 인지도 때문에 엉켜버린 방문객들의 의뢰를 정리해야 한다.",
      "choices": [
        {
          "label": "표시 용품을 내고 미라젠과 방문 목적을 구분한다",
          "result": "표시 용품을 지불하여 방문객들의 목적을 체계적으로 분류한다. 여러 부탁을 비교하고 빈틈에 힘을 싣는 요령을 배웠으며 210골드를 지불했다. 분류된 의뢰서를 미라젠에게 전달한다."
        },
        {
          "label": "루시와 밀린 부탁을 읽고 더 많은 길목을 맡는다",
          "result": "루시를 도와 밀린 의뢰 내용을 파악하며 외곽을 방어한다. 여러 부탁과 얻을 몫을 기록하는 요령을 배웠고, 개인 적의 강함은 그대로이나 적의 수가 2명 늘어났다. 기록을 마친 후 외곽을 계속 살핀다."
        },
        {
          "label": "사진을 돌려주고 방문 정리 보수를 받는다",
          "result": "사진을 돌려주며 방문객들의 안내를 마무리하고 보수를 챙긴다. 150골드를 받았으며 추가적인 요령이나 변화는 없다. 다음 방문객을 맞이할 준비를 한다."
        }
      ]
    },
    {
      "key": "ft_laxus_short_reply",
      "story": "렉서스가 뒤쪽은 자신이 맡겠다고 짧게 말하자 나츠는 먼저 가라는 말이냐며 돌아선다. 렉서스는 아직 돌아올 쪽의 이야기를 끝내지 않았다고 하고 루시는 두 사람이 다른 답을 들었다고 한다. 먼저 말의 끝을 확인할지 바깥 일을 맡을지 정한다.",
      "intro": "렉서스의 짧은 의사소통으로 인해 발생한 오해를 바로잡아야 한다.",
      "choices": [
        {
          "label": "표시 용품을 내고 렉서스가 남긴 뒤쪽을 확인한다",
          "result": "표시 용품을 지불하고 렉서스의 의도를 정확히 파악하기 위해 뒤쪽을 확인한다. 큰 상대의 빈틈에 힘을 집중하는 대신 공격력 일부를 낮춘 성장 요령을 배웠으며 220골드를 지불했다. 확인된 내용을 나츠에게 전달한다."
        },
        {
          "label": "나츠와 더 강한 적이 오가는 앞쪽을 맡는다",
          "result": "나츠와 협력하여 앞쪽의 위협에 대응한다. 공격에 힘을 싣고 작은 상대를 처리하는 요령을 배웠고, 개인 적의 강함이 1 상승했으며 적의 수가 1명 늘어났다. 전방을 방어하며 나츠와 호흡을 맞춘다."
        },
        {
          "label": "맡을 구역을 줄이고 남은 연락을 전달한다",
          "result": "담당 구역을 축소하는 대신 남은 연락 사항을 전달하는 데 집중한다. 130골드를 받았으며 추가적인 요령이나 변화는 없다. 연락이 완료된 후 주변 상황을 정리한다."
        }
      ]
    },
    {
      "key": "ft_gildarts_wall",
      "story": "길다트가 무심코 지나간 쪽의 벽이 부서져 사람들이 문이 어디였는지 묻는다. 미라젠은 남은 문틀 옆으로 짐을 모으지 말자고 하고 길다트는 자신이 지나온 쪽을 돌아본다. 네가 파손 자리를 정리할지 바깥 길을 맡을지 정해야 한다.",
      "intro": "길다트의 파괴적인 힘으로 인해 발생한 파손 부위를 수습해야 한다.",
      "choices": [
        {
          "label": "표시 용품을 내고 길다트와 손이 닿는 간격을 짚는다",
          "result": "표시 용품을 지불하고 길다트의 이동 경로와 안전 거리를 확보한다. 간격을 재며 강한 방어에 힘을 모으는 요령을 배웠으며 240골드를 지불했다. 안전 거리를 확보한 후 이동 경로를 안내한다."
        },
        {
          "label": "엘자와 더 강한 적이 오가는 바깥 자리를 맡는다",
          "result": "엘자와 협력하여 외곽의 강력한 적들을 상대한다. 공격 방향과 빈틈을 고르는 요령을 배웠고, 개인 적의 강함이 1 상승했으며 적의 수가 1명 늘어났다. 외곽 경계에 집중한다."
        },
        {
          "label": "강한 적이 오는 입구를 줄이고 파편 정리 보수를 받는다",
          "result": "입구 쪽 방어 범위를 좁히는 대신 파편을 정리하여 보수를 받는다. 140골드를 받았으며 개인 적의 강함이 1 감소했다. 파편 정리를 마친 후 입구를 재점검한다."
        },
        {
          "label": "안쪽 파편만 정리하고 물약을 받는다",
          "result": "내부의 파편을 정리하는 데 집중한다. 물약 2개를 보급받았으며 추가적인 요령이나 변화는 없다. 파편 정리를 끝내고 내부를 재정비한다."
        }
      ]
    },
    {
      "key": "ft_lucy_unfinished",
      "story": "루시가 쓴 이야기를 읽던 사람이 결말보다 앞에서 왜 그 길을 택했냐고 묻는다. 루시는 뒤에 답이 있다며 넘기려다가 독자가 멈춘 줄을 다시 본다. 해피는 다음 페이지가 아니라 방금 줄부터 읽어 보자고 한다.",
      "intro": "루시의 소설을 읽는 독자와의 소통에서 발생하는 흐름을 조율한다.",
      "choices": [
        {
          "label": "종이 값을 내고 루시와 독자가 멈춘 갈래를 읽는다",
          "result": "종이 값을 지불하고 독자가 궁금해하는 지점을 함께 읽어준다. 다른 갈래를 읽고 빈틈을 찾는 요령을 배웠으며 170골드를 지불했다. 독자의 질문에 답하며 이야기를 이어간다."
        },
        {
          "label": "루시와 다른 부탁을 기록하고 더 많은 길목을 맡는다",
          "result": "루시를 도와 다른 의뢰를 기록하며 외곽 길목을 방어한다. 여러 부탁과 얻을 몫을 기록하는 요령을 배웠고, 개인 적의 강함은 그대로이나 적의 수가 1명 늘어났다. 기록을 마친 후 외곽을 감시한다."
        },
        {
          "label": "읽은 종이를 정리하고 전달 보수를 받는다",
          "result": "읽은 종이들을 정리하고 관련 보수를 챙긴다. 120골드를 받았으며 추가적인 요령이나 변화는 없다. 정리가 끝난 후 다음 의뢰를 확인한다."
        }
      ]
    }
  ]
}
